	TabInactiveBg tcell.Color
	TabInactiveFg tcell.Color

	// 文本颜色标签（用于 tview DynamicColors）
	UserMsg   string // 用户输入
	ToolCall  string // 工具调用
	ToolOK    string // 工具成功
	ToolErr   string // 工具失败
	RoleChg   string // 角色切换
	TaskDone  string // 任务完成
