// fuzzyMatch 检查 pattern 是否按字符顺序出现在 target 中（模糊匹配）。
func fuzzyMatch(target, pattern string) bool {
	if pattern == "" {
		return false
	}
	ti := 0
	for pi := 0; pi < len(pattern); pi++ {
		found := false
		for ti < len(target) {
			if target[ti] == pattern[pi] {
				ti++
				found = true
				break
			}
			ti++
		}
		if !found {
			return false
		}
	}
	return true
}

