			if isLiteral(re.String()) && !strings.Contains(content, re.String()) {
				return nil
			}
		}

		lines := strings.Split(content, "\n")
		for i, line := range lines {
			if totalMatches >= maxGrepResults {
				return fmt.Errorf("limit") // 用 error 中断 Walk
			}
			if re.MatchString(line) {
				totalMatches++
