import (
	"os"
	"path/filepath"
	"testing"
)

func TestCheckPath(t *testing.T) {
	// 设置工作区为临时目录
	tmpDir := t.TempDir()
	SetWorkspace(tmpDir)

	// 在工作区内创建子目录和文件
	validSub := filepath.Join(tmpDir, "subdir")
	os.Mkdir(validSub, 0755)
	validFile := filepath.Join(tmpDir, "test.go")
	os.WriteFile(validFile, []byte("package main"), 0644)

	tests := []struct {
		name    string
		path    string
		wantErr bool
	}{
		// 工作区内路径
		{name: "workspace root", path: tmpDir, wantErr: false},
		{name: "subdir", path: "subdir", wantErr: false},
		{name: "file", path: "test.go", wantErr: false},

		// 相对路径但不越界
		{name: "nested relative", path: "subdir/../test.go", wantErr: false},
		{name: "dot", path: ".", wantErr: false},

		// 越界路径
		{name: "parent dir", path: "..", wantErr: true},
		{name: "parent file", path: "../outside.txt", wantErr: true},
		{name: "deep escape", path: "../../etc/passwd", wantErr: true},
		{name: "absolute escape", path: "/etc/passwd", wantErr: true},
		{name: "Windows absolute escape", path: "C:\\Windows\\System32", wantErr: true},
		{name: "sandwich escape", path: "subdir/../../etc", wantErr: true},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			err := CheckPath(tt.path)
			if (err != nil) != tt.wantErr {
				t.Errorf("CheckPath(%q) error=%v, wantErr=%v", tt.path, err, tt.wantErr)
			}
		})
	}
}

func TestCheckPathUninitialized(t *testing.T) {
	// 未设置工作区时不应拦截
	oldWs := workspace
	workspace = ""
	defer func() { workspace = oldWs }()

	if err := CheckPath("../anything"); err != nil {
		t.Errorf("未初始化时不应拦截，但返回了错误: %v", err)
	}
}

func TestCheckShell(t *testing.T) {
	tmpDir := t.TempDir()
	SetWorkspace(tmpDir)

	tests := []struct {
		name    string
		cmd     string
		wantErr bool
	}{
		// 安全命令
		{name: "no cd", cmd: "go build ./...", wantErr: false},
		{name: "cd to valid sub", cmd: "cd subdir && ls", wantErr: false},

		// cd 越界
		{name: "cd parent", cmd: "cd ..", wantErr: true},
		{name: "cd absolute outside", cmd: "cd /etc", wantErr: true},
		{name: "cd Windows outside", cmd: "cd C:\\Windows", wantErr: true},
		{name: "cd with quotes", cmd: "cd \"..\"", wantErr: true},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			err := CheckShell(tt.cmd)
			if (err != nil) != tt.wantErr {
				t.Errorf("CheckShell(%q) error=%v, wantErr=%v", tt.cmd, err, tt.wantErr)
			}
		})
	}
}

func TestCheckShellUninitialized(t *testing.T) {
	oldWs := workspace
	workspace = ""
	defer func() { workspace = oldWs }()

	if err := CheckShell("cd /etc"); err != nil {
		t.Errorf("未初始化时不应拦截，但返回了错误: %v", err)
	}
}

package tools

import (
	"testing"
)

func TestIsTextFile(t *testing.T) {
	tests := []struct {
		path     string
		expected bool
	}{
		{"main.go", true},
		{"index.js", true},
		{"style.css", true},
		{"data.json", true},
		{"readme.md", true},
		{"Dockerfile", true},
		{"Makefile", true},
		{"dockerfile.prod", true},
		{"app.py", true},
		{"Cargo.toml", true},
		{"go.mod", true},
		{"go.sum", true},
		{"src/main.rs", true},
		{"image.png", false},
		{"data.bin", false},
		{"archive.tar.gz", false},
		{"binary.exe", false},
		{"photo.jpg", false},
		{"video.mp4", false},
	}

	for _, tt := range tests {
		t.Run(tt.path, func(t *testing.T) {
			if got := isTextFile(tt.path); got != tt.expected {
				t.Errorf("isTextFile(%q) = %v, want %v", tt.path, got, tt.expected)
			}
		})
	}
}

func TestIsLiteral(t *testing.T) {
	tests := []struct {
		s        string
		expected bool
	}{
		{"hello", true},
		{"TODO", true},
		{"func main", true},
		{"a+b", false},   // + is regex meta
		{"foo.bar", false}, // . is regex meta
		{"test*", false},
		{"[abc]", false},
		{"a(b)", false},
		{"x|y", false},
		{"^start", false},
		{"end$", false},
		{"\\escape", false},
		{"", true},
	}

	for _, tt := range tests {
		t.Run(tt.s, func(t *testing.T) {
			if got := isLiteral(tt.s); got != tt.expected {
				t.Errorf("isLiteral(%q) = %v, want %v", tt.s, got, tt.expected)
			}
		})
	}
}

package llm

import (
	"encoding/json"
	"testing"
)

func TestParseXMLToolCalls_Single(t *testing.T) {
	content := `<tool_call>
{"name": "read_file", "arguments": {"path": "main.go"}}
</tool_call>`

	calls := parseXMLToolCalls(content)
	if len(calls) != 1 {
		t.Fatalf("expected 1 call, got %d", len(calls))
	}
	if calls[0].Function.Name != "read_file" {
		t.Errorf("name = %q, want read_file", calls[0].Function.Name)
	}

	var args struct {
		Path string `json:"path"`
	}
	if err := json.Unmarshal([]byte(calls[0].Function.Arguments), &args); err != nil {
		t.Fatal(err)
	}
	if args.Path != "main.go" {
		t.Errorf("path = %q, want main.go", args.Path)
	}
}

func TestParseXMLToolCalls_Multiple(t *testing.T) {
	content := `一些文本
<tool_call>
{"name": "read_file", "arguments": {"path": "main.go"}}
</tool_call>
中间文本
<tool_call>
{"name": "list_dir", "arguments": {"path": "."}}
</tool_call>
更多文本`

	calls := parseXMLToolCalls(content)
	if len(calls) != 2 {
		t.Fatalf("expected 2 calls, got %d", len(calls))
	}
	if calls[0].Function.Name != "read_file" {
		t.Errorf("call[0] = %q, want read_file", calls[0].Function.Name)
	}
	if calls[1].Function.Name != "list_dir" {
		t.Errorf("call[1] = %q, want list_dir", calls[1].Function.Name)
	}
}

func TestParseXMLToolCalls_NoToolCalls(t *testing.T) {
	calls := parseXMLToolCalls("纯文本回复，没有工具调用")
	if len(calls) != 0 {
		t.Errorf("expected 0 calls, got %d", len(calls))
	}
}

func TestParseXMLToolCalls_InvalidJSON(t *testing.T) {
	content := `<tool_call>
{not valid json}
</tool_call>`

	calls := parseXMLToolCalls(content)
	if len(calls) != 0 {
		t.Errorf("expected 0 calls for invalid JSON, got %d", len(calls))
	}
}

func TestParseXMLToolCalls_NoNewlines(t *testing.T) {
	content := `<tool_call>{"name": "execute_shell", "arguments": {"command": "go build"}}</tool_call>`

	calls := parseXMLToolCalls(content)
	if len(calls) != 1 {
		t.Fatalf("expected 1 call, got %d", len(calls))
	}
	if calls[0].Function.Name != "execute_shell" {
		t.Errorf("name = %q, want execute_shell", calls[0].Function.Name)
	}
}

