// Package context 上下文工程模块。
// 提供项目扫描、上下文构建、摘要压缩等功能。
package context

import (
	"fmt"
	"os"
	"path/filepath"
	"sort"
	"strings"

	"golang.org/x/mod/modfile"
)

// ProjectInfo 项目扫描结果的结构化摘要。
type ProjectInfo struct {
	Language    string   // Go / Python / Node / Rust / Unknown
	RootFiles   []string // 根目录下的关键文件
	ModuleName  string   // Go module 名
	GoVersion   string   // Go 版本
	DirectDeps  []string // 直接依赖
	SubModules  []string // 子模块目录（如 internal/, ui/, cmd/）
	FileCounts  map[string]int // 按扩展名统计文件数
	EntryPoints []string // 入口文件（main.go, index.js 等）
}

// Scan 扫描工作目录，生成项目信息摘要。
func Scan(workspace string) (*ProjectInfo, error) {
	info := &ProjectInfo{
		FileCounts: map[string]int{},
	}

	// 解析 go.mod
	if data, err := os.ReadFile(filepath.Join(workspace, "go.mod")); err == nil {
		f, err := modfile.Parse("go.mod", data, nil)
		if err == nil {
			info.Language = "Go"
			info.ModuleName = f.Module.Mod.Path
			if f.Go != nil {
				info.GoVersion = f.Go.Version
			}
			for _, r := range f.Require {
				if !r.Indirect {
					info.DirectDeps = append(info.DirectDeps, r.Mod.Path+"@"+r.Mod.Version)
				}
			}
		}
	}

	// 检测其他语言
	if info.Language == "" {
		if _, err := os.Stat(filepath.Join(workspace, "package.json")); err == nil {
			info.Language = "Node.js"
		} else if _, err := os.Stat(filepath.Join(workspace, "Cargo.toml")); err == nil {
			info.Language = "Rust"
		} else if _, err := os.Stat(filepath.Join(workspace, "pyproject.toml")); err == nil {
			info.Language = "Python"
		} else {
			info.Language = "Unknown"
		}
	}

	// 扫描根目录文件
	entries, err := os.ReadDir(workspace)
	if err == nil {
		for _, e := range entries {
			if e.IsDir() {
				continue
			}
			info.RootFiles = append(info.RootFiles, e.Name())
		}
	}
	sort.Strings(info.RootFiles)

	// 统计文件数和关键目录
	filepath.Walk(workspace, func(path string, fi os.FileInfo, err error) error {
		if err != nil {
			return nil
		}
		rel, _ := filepath.Rel(workspace, path)
		if rel == "." {
			return nil
		}

		// 跳过隐藏目录和无关目录
		if fi.IsDir() {
			base := filepath.Base(path)
			if strings.HasPrefix(base, ".") && base != "." {
				return filepath.SkipDir
			}
			switch base {
			case "node_modules", "vendor", "__pycache__", "test_output", ".aicode":
				return filepath.SkipDir
			}
			// 记录顶级子目录
			parts := strings.SplitN(rel, string(filepath.Separator), 2)
			if len(parts) == 1 {
				// 检查是否包含 Go 源码
				sf, _ := os.ReadDir(path)
				for _, s := range sf {
					if strings.HasSuffix(s.Name(), ".go") {
						info.SubModules = append(info.SubModules, parts[0]+"/")
						break
					}
				}
			}
			return nil
		}

		// 统计文件
		ext := strings.ToLower(filepath.Ext(fi.Name()))
		if ext == "" {
			ext = "(无后缀)"
		}
		info.FileCounts[ext]++

		// 检测入口文件
		base := strings.ToLower(fi.Name())
		if base == "main.go" || base == "index.js" || base == "index.ts" || base == "main.rs" {
			info.EntryPoints = append(info.EntryPoints, rel)
		}

		return nil
	})

	return info, nil
}

// Format 生成注入 LLM system prompt 的文本块。
func (info *ProjectInfo) Format() string {
	var sb strings.Builder
	sb.WriteString("<project_overview>\n")
	sb.WriteString(fmt.Sprintf("语言: %s\n", info.Language))

	if info.ModuleName != "" {
		sb.WriteString(fmt.Sprintf("模块: %s", info.ModuleName))
		if info.GoVersion != "" {
			sb.WriteString(fmt.Sprintf(" (go %s)", info.GoVersion))
		}
		sb.WriteString("\n")
	}

	if len(info.EntryPoints) > 0 {
		sb.WriteString(fmt.Sprintf("入口: %s\n", strings.Join(info.EntryPoints, ", ")))
	}
	if len(info.SubModules) > 0 {
		sb.WriteString(fmt.Sprintf("子模块: %s\n", strings.Join(info.SubModules, " ")))
	}
	if len(info.DirectDeps) > 0 {
		sb.WriteString(fmt.Sprintf("直接依赖 (%d): %s\n", len(info.DirectDeps),
			strings.Join(trimDeps(info.DirectDeps, 8), ", ")))
	}

	// 文件统计
	var extStats []string
	for ext, count := range info.FileCounts {
		extStats = append(extStats, fmt.Sprintf("%s=%d", ext, count))
	}
	sort.Strings(extStats)
	sb.WriteString(fmt.Sprintf("文件: %s\n", strings.Join(extStats, ", ")))

	sb.WriteString("</project_overview>")
	return sb.String()
}

func trimDeps(deps []string, max int) []string {
	if len(deps) <= max {
		return deps
	}
	return append(deps[:max], fmt.Sprintf("...及其他 %d 个", len(deps)-max))
}

